import argparse
import json
from pathlib import Path


def search_key(title):
    return title.casefold()


def load(path="data/books.json"):
    return json.loads(Path(path).read_text())


def build_export(rows):
    """Build the search export, ordered by key then identity so output is deterministic
    regardless of the import order of the source data."""
    books = [
        {"isbn": r["isbn"], "edition": r["edition"], "title": r["title"],
         "active": r["active"], "key": search_key(r["title"])}
        for r in rows
    ]
    books.sort(key=lambda b: (b["key"], b["isbn"], b["edition"]))
    return {"books": books}


def write_export(export, path):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(export, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


def prefix_search(export, prefix):
    """Return books whose folded key starts with the folded prefix; titles are untouched."""
    folded = search_key(prefix)
    return [b for b in export["books"] if b["key"].startswith(folded)]


def print_inventory():
    rows = load()
    print(json.dumps({"rows": len(rows), "unique_isbns": len({r["isbn"] for r in rows}),
                      "keys": [search_key(r["title"]) for r in rows]}, ensure_ascii=False))


def main(argv=None):
    parser = argparse.ArgumentParser(description="Library catalogue prefix search")
    commands = parser.add_subparsers(dest="command")
    export_cmd = commands.add_parser("export", help="write the search export")
    export_cmd.add_argument("output", nargs="?", default="build/search.json")
    search_cmd = commands.add_parser("search", help="prefix-search titles")
    search_cmd.add_argument("prefix")
    args = parser.parse_args(argv)

    if args.command == "export":
        write_export(build_export(load()), args.output)
    elif args.command == "search":
        for book in prefix_search(build_export(load()), args.prefix):
            print(f'{book["isbn"]}\t{book["edition"]}\t{book["title"]}')
    else:
        print_inventory()


if __name__ == "__main__":
    main()
EOF
cat >> tests/test_catalog.py <<'EOF'


def test_export_keeps_title_and_folds_key():
    book = next(b for b in build_export(load())["books"] if b["title"].startswith("Straße"))
    assert book["key"] == "strasse Atlas".casefold()
    assert len(book["key"]) == len(book["title"]) + 1


def test_export_has_every_edition_in_stable_order():
    books = build_export(load())["books"]
    assert [(b["isbn"], b["edition"]) for b in books] == [
        ("9780000000035", "paper"),
        ("9780000000011", "large-print"),
        ("9780000000011", "paper"),
        ("9780000000028", "paper"),
    ]
    assert set(books[0]) == {"isbn", "edition", "title", "active", "key"}


def test_prefix_search_folds_the_query():
    export = build_export(load())
    assert [b["edition"] for b in prefix_search(export, "STRASSE")] == ["large-print", "paper"]
    assert [b["title"] for b in prefix_search(export, "APP")] == ["apple Almanac"]
    assert prefix_search(export, "nothing") == []
